Multiline data arguments: {"code": "return inputs.text;", "inputs": {"text": "first\nsecond\n"}}
  codemode(args: { "code": string; "inputs"?: {  }; "language"?: "javascript" | "js"; "repair_of"?: string /* pattern "^cmr_[A-Za-z0-9_-]{6,64}$" */ })
